if mibBuilder.loadTexts: rttMplsVpnMonTypeTable.setStatus('current')
if mibBuilder.loadTexts: rttMplsVpnMonTypeTable.setDescription('A table that contains Auto SAA L3 MPLS VPN configured RTT\n        operation specific definitions.\n\n        This table is controlled via the rttMplsVpnMonCtrlTable.\n        Entries in this table are created via the\n        rttMplsVpnMonCtrlStatus object.')
rttMplsVpnMonTypeEntry = MibTableRow((1, 3, 6, 1, 4, 1, 9, 9, 42, 1, 2, 16, 1), ).setMaxAccess("notaccessible")
rttMplsVpnMonCtrlEntry.registerAugmentions(("CISCO-RTTMON-MIB", "rttMplsVpnMonTypeEntry"))
