if mibBuilder.loadTexts: rttMplsVpnMonTypeEntry.setStatus('current')
if mibBuilder.loadTexts: rttMplsVpnMonTypeEntry.setDescription('A list of objects that define RTT operation specific\n        configuration for an Auto SAA L3 MPLS VPN.')
rttMplsVpnMonTypeInterval = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 42, 1, 2, 16, 1, 1), Integer32().subtype(subtypeSpec=ValueRangeConstraint(1, 60000)).clone(20)).setUnits('milliseconds').setMaxAccess("readcreate")
if mibBuilder.loadTexts: rttMplsVpnMonTypeInterval.setStatus('current')
if mibBuilder.loadTexts: rttMplsVpnMonTypeInterval.setDescription('This value represents the inter-packet delay between packets\n        and is in milliseconds. This value is currently used for\n        Jitter probe. This object is applicable to jitter probe only.\n\n        The usage of this value in RTT operation is same as\n        rttMonEchoAdminInterval.')
rttMplsVpnMonTypeNumPackets = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 42, 1, 2, 16, 1, 2), Integer32().subtype(subtypeSpec=ValueRangeConstraint(1, 60000)).clone(10)).setMaxAccess("readcreate")
if mibBuilder.loadTexts: rttMplsVpnMonTypeNumPackets.setStatus('current')
if mibBuilder.loadTexts: rttMplsVpnMonTypeNumPackets.setDescription('This value represents the number of packets that need to be\n        transmitted. This value is currently used for Jitter probe.\n        This object is applicable to jitter probe only.\n\n        The usage of this value in RTT operation is same as\n        rttMonEchoAdminNumPackets.')
rttMplsVpnMonTypeDestPort = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 42, 1, 2, 16, 1, 3), Integer32().subtype(subtypeSpec=ValueRangeConstraint(1, 65536))).setMaxAccess("readcreate")
if mibBuilder.loadTexts: rttMplsVpnMonTypeDestPort.setStatus('current')
if mibBuilder.loadTexts: rttMplsVpnMonTypeDestPort.setDescription("This object represents the target's port number to which the\n        packets need to be sent.\n\n        This value will be configured as target port for all the\n        operations that is going to be configured \n\n        The usage of this value is same as rttMonEchoAdminTargetPort\n        in RTT operation. This object is applicable to jitter type.\n\n        If this object is not being set random port will be used as\n        destination port.")
rttMplsVpnMonTypeSecFreqType = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 42, 1, 2, 16, 1, 4), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4))).clone(namedValues=NamedValues(("none", 1), ("timeout", 2), ("connectionLoss", 3), ("both", 4))).clone('none')).setMaxAccess("readcreate")
if mibBuilder.loadTexts: rttMplsVpnMonTypeSecFreqType.setStatus('current')
if mibBuilder.loadTexts: rttMplsVpnMonTypeSecFreqType.setDescription("This object specifies the reaction type for which the\n        rttMplsVpnMonTypeSecFreqValue should be applied.\n\n        The Value 'timeout' will cause secondary frequency to be set\n        for frequency on timeout condition.\n\n        The Value 'connectionLoss' will cause secondary frequency to\n        be set for frequency on connectionloss condition.\n\n        The Value 'both' will cause secondary frequency to be set for\n        frequency on either of timeout/connectionloss condition.\n\n        Notifications must be configured on corresponding reaction type\n        in order to rttMplsVpnMonTypeSecFreqValue get effect.\n\n        When LSP Path Discovery is enabled for this row the following\n        rttMplsVpnMonReactLpdNotifyType notifications must be\n        configured in order to rttMplsVpnMonTypeSecFreqValue get effect.\n          - 'lpdGroupStatus' or 'lpdAll'.\n\n        Since the Frequency of the operation changes the stats will be\n        collected in new bucket.\n\n        If any of the reaction type (timeout/connectionLoss) occurred\n        for an operation configured by this Auto SAA L3 MPLS VPN and\n        the following conditions are satisfied, the frequency of the\n        operation will be changed to rttMplsVpnMonTypeSecFreqValue.\n\n          1) rttMplsVpnMonTypeSecFreqType is set for a reaction type\n          (timeout/connectionLoss).\n          2) A notification is configured for the same reaction type\n          (timeout/connectionLoss).\n\n        When LSP Path Discovery is enabled for this row, if any of the\n        reaction type (timeout/connectionLoss) occurred for 'single\n        probes' configured by this Auto SAA L3 MPLS VPN and the\n        following conditions are satisfied, the secondary frequency\n        rttMplsVpnMonTypeSecFreqValue will be applied to the\n        'lspGroup' probe.\n\n          1) rttMplsVpnMonTypeSecFreqType is set for a reaction type\n          (timeout/connectionLoss/both).\n          2) rttMplsVpnMonReactLpdNotifyType object must be set to\n          value of 'lpdGroupStatus' or 'lpdAll'.\n\n        The frequency of the individual operations will be restored to\n        original frequency once the trap is sent.")
rttMplsVpnMonTypeSecFreqValue = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 42, 1, 2, 16, 1, 5), Integer32().subtype(subtypeSpec=ValueRangeConstraint(1, 604800)).clone(60)).setMaxAccess("readcreate")
if mibBuilder.loadTexts: rttMplsVpnMonTypeSecFreqValue.setStatus('current')
if mibBuilder.loadTexts: rttMplsVpnMonTypeSecFreqValue.setDescription('This object represents the value that needs to be applied to\n        secondary frequency of individual RTT operations configured by\n        Auto SAA L3 MPLS VPN.\n\n        Setting rttMplsVpnMonTypeSecFreqValue without setting\n        rttMplsVpnMonTypeSecFreqType will not have any effect.')
rttMplsVpnMonTypeLspSelector = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 42, 1, 2, 16, 1, 6), OctetString().clone('7F 00 00 01')).setMaxAccess("readcreate")
if mibBuilder.loadTexts: rttMplsVpnMonTypeLspSelector.setStatus('current')
if mibBuilder.loadTexts: rttMplsVpnMonTypeLspSelector.setDescription('A string which specifies the address of the local host\n        (127.X.X.X).\n\n        This object will be used as lsp-selector in MPLS RTT\n        operations configured by the Auto SAA L3 MPLS VPN.\n\n        When LSP Path Discovery is enabled for the row, this object will\n        be used to indicate the base LSP selector value to be used in\n        the LSP Path Discovery.\n\n        This value of this object is significant in MPLS load\n        balancing scenario. This value will be used as one of the\n        parameter in that load balancing.')
rttMplsVpnMonTypeLSPReplyMode = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 42, 1, 2, 16, 1, 7), RttMonLSPPingReplyMode().clone('replyIpv4Udp')).setMaxAccess("readcreate")
if mibBuilder.loadTexts: rttMplsVpnMonTypeLSPReplyMode.setStatus('current')
if mibBuilder.loadTexts: rttMplsVpnMonTypeLSPReplyMode.setDescription('This object specifies the reply mode for the LSP Echo\n        requests originated by the operations configured by the\n        Auto SAA L3 MPLS VPN.\n\n        This object is currently used by echo and pathEcho.')
rttMplsVpnMonTypeLSPTTL = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 42, 1, 2, 16, 1, 8), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 255)).clone(0)).setMaxAccess("readcreate")
if mibBuilder.loadTexts: rttMplsVpnMonTypeLSPTTL.setStatus('current')
if mibBuilder.loadTexts: rttMplsVpnMonTypeLSPTTL.setDescription("This object represents the TTL setting for MPLS echo request\n        packets originated by the operations configured by the\n        Auto SAA L3 MPLS VPN.\n\n        This object is currently used by echo and pathEcho.\n\n        For 'echo' the default TTL will be set to 255.\n        For 'pathEcho' the default will be set to 30.\n\n        Note: This object cannot be set to the value of 0. The\n        default value of 0 signifies the default TTL values will be\n        used for 'echo' and 'pathEcho'.")
rttMplsVpnMonTypeLSPReplyDscp = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 42, 1, 2, 16, 1, 9), Integer32().subtype(subtypeSpec=ConstraintsUnion(ValueRangeConstraint(0, 63), ValueRangeConstraint(255, 255), )).clone(255)).setMaxAccess("readcreate")
if mibBuilder.loadTexts: rttMplsVpnMonTypeLSPReplyDscp.setStatus('current')
if mibBuilder.loadTexts: rttMplsVpnMonTypeLSPReplyDscp.setDescription('This object specifies the DSCP value to be set in the IP header\n        of the LSP echo reply packet.\n        The value of this object will be in range of DiffServ codepoint\n        values between 0 to 63.\n\n        Note: This object cannot be set to value of 255. This default\n        value specifies that DSCP is not set for this row.')
rttMplsVpnMonTypeLpdMaxSessions = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 42, 1, 2, 16, 1, 10), Integer32().subtype(subtypeSpec=ValueRangeConstraint(1, 15)).clone(1)).setMaxAccess("readcreate")
if mibBuilder.loadTexts: rttMplsVpnMonTypeLpdMaxSessions.setStatus('current')
if mibBuilder.loadTexts: rttMplsVpnMonTypeLpdMaxSessions.setDescription('This object represents the number of concurrent path discovery\n        requests that will be active at one time per MPLS VPN control\n        row. This object is meant for reducing the time for discovery\n        of all the paths to the target in a large customer network.\n        However its value should be chosen such that it does not cause\n        any performance impact.\n\n        Note: If the customer network has low end routers in the Core\n        it is recommended to keep this value low.')
rttMplsVpnMonTypeLpdSessTimeout = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 42, 1, 2, 16, 1, 11), Integer32().subtype(subtypeSpec=ValueRangeConstraint(1, 900)).clone(120)).setUnits('seconds').setMaxAccess("readcreate")
if mibBuilder.loadTexts: rttMplsVpnMonTypeLpdSessTimeout.setStatus('current')
if mibBuilder.loadTexts: rttMplsVpnMonTypeLpdSessTimeout.setDescription('This object specifies the maximum allowed duration of a\n        particular tree trace request.\n\n        If no response is received in configured time the request will\n        be considered a failure.')
rttMplsVpnMonTypeLpdEchoTimeout = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 42, 1, 2, 16, 1, 12), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 604800000)).clone(5000)).setUnits('milliseconds').setMaxAccess("readcreate")
